<?php
require 'page-guard.php';require '../config/db_conn.php';require '../includes/teacher-profile-schema.php';ensureTeacherProfileColumns($conn);require 'components.php';
$assignedSection=$_SESSION['teacher-section'];$section=trim($_GET['section']??$assignedSection);
$teacherId=(int)($_SESSION['teacher-id']??0);$teacherSubject='Subject not assigned';if($teacherId){$teacherQuery=$conn->prepare('SELECT SUBJECT FROM teachers WHERE TEACHER_ID=? LIMIT 1');$teacherQuery->bind_param('i',$teacherId);$teacherQuery->execute();$teacherSubject=$teacherQuery->get_result()->fetch_assoc()['SUBJECT']??$teacherSubject;}
$sectionResult=$conn->query("SELECT SECTION, COUNT(*) student_count FROM students WHERE SECTION IS NOT NULL AND SECTION<>'' GROUP BY SECTION ORDER BY SECTION");$sections=[];while($item=$sectionResult->fetch_assoc())$sections[]=$item;
$allowed=$conn->prepare('SELECT 1 FROM students WHERE SECTION=? LIMIT 1');$allowed->bind_param('s',$section);$allowed->execute();if(!$allowed->get_result()->num_rows){http_response_code(404);exit('That section has no students.');}
$today=date('Y-m-d');$stmt=$conn->prepare("SELECT s.*,(SELECT COUNT(*) FROM attendance a WHERE TRIM(a.STUDENT_ID)=TRIM(s.STUDENT_ID) AND DATE(a.TIME_IN)=?) attended_today FROM students s WHERE s.SECTION=? ORDER BY s.STUDENT_NAME");$stmt->bind_param('ss',$today,$section);$stmt->execute();$students=$stmt->get_result();
teacherHead('Students');teacherShell('Students');
?>
<div class="mb-6 flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between"><div><h2 class="text-2xl font-black text-slate-900">Students</h2><p class="mt-1 text-slate-500">Choose a section to view its student list.</p></div><div class="flex gap-3"><a href="home.php" class="rounded-xl border border-slate-300 px-4 py-3 text-sm font-bold text-slate-700 hover:bg-slate-50">Attendance logs</a><input id="student-search" class="w-full rounded-xl border border-slate-300 px-4 py-3 text-sm sm:w-72" placeholder="Search name or ID"></div></div>
<section class="mb-6 rounded-2xl bg-white p-5 shadow-sm ring-1 ring-slate-200"><p class="text-xs font-bold uppercase tracking-widest text-slate-500">Current sections</p><div class="mt-4 grid gap-3 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4"><?php foreach($sections as $item):$isActive=$item['SECTION']===$section;?><a href="students.php?section=<?= urlencode($item['SECTION']) ?>" class="rounded-xl border p-4 transition <?= $isActive?'border-blue-600 bg-blue-600 text-white shadow-lg shadow-blue-200':'border-slate-200 bg-white text-slate-900 hover:border-blue-300 hover:bg-blue-50' ?>"><span class="block text-lg font-black"><?= htmlspecialchars($item['SECTION']) ?></span><span class="mt-1 block text-sm font-bold <?= $isActive?'text-blue-100':'text-slate-600' ?>"><?= htmlspecialchars($teacherSubject) ?></span><span class="mt-1 block text-sm <?= $isActive?'text-blue-100':'text-slate-500' ?>"><?= $item['student_count'] ?> student<?= $item['student_count']==1?'':'s' ?></span></a><?php endforeach; ?></div></section>
<div class="mb-4"><h3 class="text-xl font-black text-slate-900"><?= htmlspecialchars($section) ?> students</h3><p class="mt-1 text-slate-500"><?= $students->num_rows ?> student<?= $students->num_rows===1?'':'s' ?> in this section</p></div><div class="overflow-hidden rounded-2xl bg-white shadow-sm ring-1 ring-slate-200"><div class="overflow-x-auto"><table class="min-w-full text-left text-sm"><thead class="bg-slate-50 text-xs uppercase tracking-wider text-slate-500"><tr><th class="px-5 py-4">Student</th><th class="px-5 py-4">ID</th><th class="px-5 py-4">Grade</th><th class="px-5 py-4">Section</th><th class="px-5 py-4">Today</th><th class="px-5 py-4"></th></tr></thead><tbody id="student-rows" class="divide-y divide-slate-100"><?php while($student=$students->fetch_assoc()): ?><tr class="hover:bg-slate-50"><td class="px-5 py-4"><div class="flex items-center gap-3"><img src="../<?= htmlspecialchars($student['IMAGE_PATH']) ?>" alt="" class="h-10 w-10 rounded-full object-cover"><span class="font-bold text-slate-900"><?= htmlspecialchars($student['STUDENT_NAME']) ?></span></div></td><td class="px-5 py-4 text-slate-600"><?= htmlspecialchars($student['STUDENT_ID']) ?></td><td class="px-5 py-4"><span class="rounded-full bg-violet-50 px-3 py-1 font-bold text-violet-700">Grade <?= htmlspecialchars($student['GRADE']??'—') ?></span></td><td class="px-5 py-4"><span class="rounded-full bg-blue-50 px-3 py-1 font-bold text-blue-700"><?= htmlspecialchars($student['SECTION']) ?></span></td><td class="px-5 py-4"><span class="rounded-full px-3 py-1 font-bold <?= $student['attended_today']?'bg-emerald-50 text-emerald-700':'bg-amber-50 text-amber-700' ?>"><?= $student['attended_today']?'Present':'Not recorded' ?></span></td><td class="px-5 py-4 text-right"><a class="font-bold text-blue-600" href="student-profile.php?id=<?= $student['ID'] ?>&section=<?= urlencode($section) ?>">Open profile</a></td></tr><?php endwhile; ?></tbody></table></div></div><script>document.getElementById('student-search').addEventListener('input',e=>document.querySelectorAll('#student-rows tr').forEach(row=>row.hidden=!row.textContent.toLowerCase().includes(e.target.value.toLowerCase())))</script><?php teacherFoot(); ?>
